validator:
function validate(input) {
  const [{ customer_transactions = [] }] = input;
  const ids = new Set();
  for (const [id, customer, day, amount, type] of customer_transactions) {
    if ([id, customer, day, amount, type].includes(null)) return 'No value in customer_transactions may be null.';
    if (ids.has(id)) return `transaction_id ${id} appears twice.`;
    ids.add(id);
    if (type !== 'purchase' && type !== 'refund') return `transaction_type ${type} must be 'purchase' or 'refund'.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) return `transaction_date ${day} must look like 2024-01-31.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const pad = n => String(n).padStart(2, '0');
  // Small dates sit around the 30-day boundary (2024-01-01 to 2024-01-31 is exactly 30 days).
  const dates = small ? ['2024-01-01', '2024-01-02', '2024-01-15', '2024-01-30', '2024-01-31', '2024-02-01', '2024-02-20']
    : Array.from({ length: 150 }, (_, i) => { const d = new Date(Date.UTC(2023, 11, 1 + i)); return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`; });
  const customers = small ? [101, 102, 103] : Array.from({ length: 300 }, (_, i) => 1000 + i);
  const count = small ? Math.floor(rand() * 9) : 2000;
  const customer_transactions = [];
  for (let i = 0; i < count; i++) {
    const type = rand() < (small ? 0.75 : 0.85) ? 'purchase' : 'refund';
    const amount = small ? pick([50, 80, 120, 150, 99.99]) : 1 + Math.floor(rand() * 50000) / 100;
    customer_transactions.push([i + 1, pick(customers), pick(dates), amount, type]);
  }
  return [{ customer_transactions }];
}
